24.             where Pred: AtomicInvariantPredicate<K, $value_ty, G>
25.         {
26.             open spec fn inv(k_loc: (K, int), perm_g: ($perm_ty, G)) -> bool {
27.                 let (k, loc) = k_loc;
28.                 let (perm, g) = perm_g;
29. 
30.                 perm.view().patomic == loc
31.                   && Pred::atomic_inv(k, perm.view().value, g)
